<?php
namespace App\Http\Controllers\Mitra;
use App\Http\Controllers\Controller;use App\Http\Controllers\Mitra\Concerns\ResolvesActiveMitra;use App\Http\Requests\SaveVoucherRequest;use App\Models\ServiceType;use App\Models\Voucher;use App\Services\AuditLogger;use Illuminate\Http\RedirectResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\View\View;
class VoucherController extends Controller
{use ResolvesActiveMitra;public function index(Request $r):View{abort_unless($r->user()->can('vouchers.manage'),403);return view('mitra.vouchers.index',['vouchers'=>Voucher::where('mitra_id',$this->activeMitra($r)->id)->latest()->paginate(20)]);}public function create(Request $r):View{return view('mitra.vouchers.form',['services'=>$this->activeMitra($r)->features()->where('status','enabled')->with('serviceType')->get()->pluck('serviceType')]);}public function store(SaveVoucherRequest $r,AuditLogger $audit):RedirectResponse{$mitra=$this->activeMitra($r);$allowed=$mitra->features()->where('status','enabled')->whereIn('service_type_id',$r->validated('service_type_ids'))->count();abort_unless($allowed===count($r->validated('service_type_ids')),403);DB::transaction(function()use($r,$mitra,$audit){$data=$r->safe()->except('service_type_ids');$data['code']=strtoupper($data['code']);$voucher=Voucher::create($data+['mitra_id'=>$mitra->id,'created_by'=>$r->user()->id]);$voucher->serviceTypes()->sync($r->validated('service_type_ids'));$audit->record('voucher.mitra_created',$voucher,[],$voucher->toArray(),$r->user());});return redirect()->route('mitra.vouchers.index')->with('status','Voucher Mitra dibuat.');}}
